import type {IncomingMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validators: Record<string, (value: Record<string, unknown>) => ValidationResult> = {
    user_message: validateUserMessage,
    ping: validatePingMessage,
    list_sessions: validateListSessionsMessage,
  };
  const validator = validators[message.type];
  return validator ? validator(message) : {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined && (!Number.isInteger(message.limit) || (message.limit as number) < 0)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  const beforeResult = validateCursor(message.before);
  if (!beforeResult.valid) return beforeResult;
  const before = beforeResult.before;

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(message.limit !== undefined ? {limit: message.limit as number} : {}),
      ...(before !== undefined ? {before} : {}),
    },
  };
}

function validateCursor(
  value: unknown
): {valid: true; before: {sessionId: string; updatedAt: string | number} | undefined} | {valid: false; error: string} {
  if (value === undefined) return {valid: true, before: undefined};
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return {valid: false, error: 'list_sessions before must be an object'};
  }
  const {sessionId, updatedAt} = value as Record<string, unknown>;
  if (!isValidSessionId(sessionId)) {
    return {valid: false, error: 'list_sessions before sessionId must be 1–128 characters'};
  }
  if (!isValidCursorDate(updatedAt)) {
    return {valid: false, error: 'list_sessions before updatedAt must be a valid date'};
  }
  return {valid: true, before: {sessionId, updatedAt}};
}

function isValidSessionId(value: unknown): value is string {
  return typeof value === 'string' && value.length >= 1 && value.length <= 128;
}

function isValidCursorDate(value: unknown): value is string | number {
  if (typeof value === 'string') return Number.isFinite(Date.parse(value));
  if (typeof value === 'number') return Number.isFinite(new Date(value).getTime());
  return false;
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
export function connectClient(url: string, token = 't'): WebSocket {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
}

/** Sends frames after `connected` and resolves after a ping barrier has drained earlier replies. */
export async function exchangeAfterConnect(
  url: string,
  outbound: unknown[],
  token = 't'
): Promise<{connected: {type: string; sessionId?: string}; frames: Array<{type: string; [key: string]: unknown}>}> {
  const client = connectClient(url, token);
  const frames: Array<{type: string; [key: string]: unknown}> = [];
  let connected: {type: string; sessionId?: string} = {type: ''};
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as {type: string; sessionId?: string; [key: string]: unknown};
      if (frame.type === 'connected') {
        connected = frame;
        for (const message of outbound) client.send(JSON.stringify(message));
        return;
      }
      if (frame.type === 'pong') {
        if (outbound.length === 1) frames.push(frame);
        setImmediate(resolve);
        return;
      }
      frames.push(frame);
    });
  });
  return {connected, frames};
}

/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
export function deferred(): {until: Promise<void>; release: () => void} {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release};
}

